def semver_sort(versions):
    def parse_version(v):
        # Split build metadata (after '+')
        if '+' in v:
            v, build = v.split('+', 1)
        else:
            build = ''

        # Split pre-release (after '-')
        if '-' in v:
            base, prerelease = v.split('-', 1)
            prerelease_parts = prerelease.split('.')
        else:
            base = v
            prerelease_parts = None

        # Parse MAJOR.MINOR.PATCH
        parts = base.split('.')
        major = int(parts[0])
        minor = int(parts[1]) if len(parts) > 1 else 0
        patch = int(parts[2]) if len(parts) > 2 else 0

        return (major, minor, patch, prerelease_parts)

    def compare_prerelease(pre1, pre2):
        # None means no pre-release (release version)
        # Version with pre-release sorts before version without
        if pre1 is None and pre2 is None:
            return 0
        if pre1 is None:
            return 1  # no pre-release sorts after pre-release
        if pre2 is None:
            return -1  # pre-release sorts before no pre-release

        # Both have pre-releases, compare identifier by identifier
        for i in range(max(len(pre1), len(pre2))):
            if i >= len(pre1):
                return -1  # fewer identifiers sorts first
            if i >= len(pre2):
                return 1

            id1 = pre1[i]
            id2 = pre2[i]

            # Check if both are all digits
            is_digit1 = id1.isdigit()
            is_digit2 = id2.isdigit()

            if is_digit1 and is_digit2:
                # Both numeric, compare numerically
                num1 = int(id1)
                num2 = int(id2)
                if num1 != num2:
                    return -1 if num1 < num2 else 1
            elif is_digit1:
                # Only id1 is numeric, it sorts first
                return -1
            elif is_digit2:
                # Only id2 is numeric, it sorts first
                return 1
            else:
                # Both non-numeric, compare lexically
                if id1 != id2:
                    return -1 if id1 < id2 else 1

        return 0

    def sort_key(item):
        index, version = item
        major, minor, patch, prerelease = parse_version(version)
        return (major, minor, patch, prerelease is not None, prerelease or [])

    def compare_versions(item1, item2):
        index1, v1 = item1
        index2, v2 = item2

        major1, minor1, patch1, pre1 = parse_version(v1)
        major2, minor2, patch2, pre2 = parse_version(v2)

        # Compare MAJOR.MINOR.PATCH
        if (major1, minor1, patch1) != (major2, minor2, patch2):
            return -1 if (major1, minor1, patch1) < (major2, minor2, patch2) else 1

        # Compare pre-release
        pre_cmp = compare_prerelease(pre1, pre2)
        if pre_cmp != 0:
            return pre_cmp

        # Equal precedence, keep input order
        return -1 if index1 < index2 else (1 if index1 > index2 else 0)

    indexed_versions = list(enumerate(versions))

    # Stable sort using the custom comparison
    from functools import cmp_to_key
    sorted_versions = sorted(indexed_versions, key=cmp_to_key(compare_versions))

    return [v for _, v in sorted_versions]

